values (
  'en-boxing-trivia',
  'Boxing History Trivia: Legends of the Ring',
  'Weight classes, legendary rivalries and the golden eras of the heavyweight division: test how much you know about the sweet science.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"Which champion made famous the motto ''float like a butterfly, sting like a bee''?","options":[{"id":"a","text":"Mike Tyson","is_correct":false},{"id":"b","text":"Muhammad Ali","is_correct":true},{"id":"c","text":"Joe Frazier","is_correct":false},{"id":"d","text":"George Foreman","is_correct":false}],"explanation":"Muhammad Ali''s catchphrase captured his style: light on his feet, sharp with his jab."},{"id":"q2","question":"In which city was the 1974 ''Rumble in the Jungle'' fought?","options":[{"id":"a","text":"Manila, Philippines","is_correct":false},{"id":"b","text":"Las Vegas, United States","is_correct":false},{"id":"c","text":"Kinshasa, Zaire","is_correct":true},{"id":"d","text":"London, England","is_correct":false}],"explanation":"Ali regained the heavyweight title from George Foreman in Kinshasa, in the country now called the Democratic Republic of the Congo."},{"id":"q3","question":"Who became the youngest heavyweight champion in history in 1986, aged just 20?","options":[{"id":"a","text":"Evander Holyfield","is_correct":false},{"id":"b","text":"Lennox Lewis","is_correct":false},{"id":"c","text":"Riddick Bowe","is_correct":false},{"id":"d","text":"Mike Tyson","is_correct":true}],"explanation":"Mike Tyson knocked out Trevor Berbick to win the WBC heavyweight title at 20 years and 4 months."},{"id":"q4","question":"Which heavyweight champion retired undefeated with a 49-0 record?","options":[{"id":"a","text":"Rocky Marciano","is_correct":true},{"id":"b","text":"Joe Louis","is_correct":false},{"id":"c","text":"Jack Dempsey","is_correct":false},{"id":"d","text":"Sonny Liston","is_correct":false}],"explanation":"Rocky Marciano retired in 1956 after 49 wins, 43 of them by knockout, and never lost as a professional."},{"id":"q5","question":"How many rounds does a modern men''s world championship boxing match have?","options":[{"id":"a","text":"10","is_correct":false},{"id":"b","text":"12","is_correct":true},{"id":"c","text":"15","is_correct":false},{"id":"d","text":"8","is_correct":false}],"explanation":"Men''s title bouts were shortened from 15 to 12 rounds during the 1980s; women''s title bouts use ten rounds."},{"id":"q6","question":"Which Panamanian champion was nicknamed ''Hands of Stone''?","options":[{"id":"a","text":"Alexis Argüello","is_correct":false},{"id":"b","text":"Julio César Chávez","is_correct":false},{"id":"c","text":"Carlos Monzón","is_correct":false},{"id":"d","text":"Roberto Durán","is_correct":true}],"explanation":"Roberto Durán, ''Manos de Piedra'', won world titles in four weight classes."},{"id":"q7","question":"Which weight class sits directly below heavyweight?","options":[{"id":"a","text":"Light heavyweight","is_correct":false},{"id":"b","text":"Cruiserweight","is_correct":true},{"id":"c","text":"Super middleweight","is_correct":false},{"id":"d","text":"Welterweight","is_correct":false}],"explanation":"Cruiserweight, capped at 200 lb in its classic form, bridges the gap to heavyweight."},{"id":"q8","question":"Which heavyweight champion was known as ''The Brown Bomber''?","options":[{"id":"a","text":"Muhammad Ali","is_correct":false},{"id":"b","text":"Larry Holmes","is_correct":false},{"id":"c","text":"Joe Louis","is_correct":true},{"id":"d","text":"Floyd Patterson","is_correct":false}],"explanation":"Joe Louis held the heavyweight crown for nearly 12 years and defended it 25 times, a record for the division."}]'::jsonb,
  null,
  array['boxing', 'sports', 'heavyweight', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
