  '[{"id":"q1","question":"¿Qué campeón hizo famosa la frase «vuela como una mariposa, pica como una abeja»?","options":[{"id":"a","text":"Mike Tyson","is_correct":false},{"id":"b","text":"Joe Frazier","is_correct":false},{"id":"c","text":"Muhammad Ali","is_correct":true},{"id":"d","text":"George Foreman","is_correct":false}],"explanation":"La frase de Muhammad Ali resumía su estilo: pies ligeros y un jab afilado."},{"id":"q2","question":"¿En qué ciudad se disputó el «Rumble in the Jungle» de 1974?","options":[{"id":"a","text":"Manila, Filipinas","is_correct":false},{"id":"b","text":"Kinshasa, Zaire","is_correct":true},{"id":"c","text":"Las Vegas, Estados Unidos","is_correct":false},{"id":"d","text":"Londres, Inglaterra","is_correct":false}],"explanation":"Ali recuperó el título pesado ante George Foreman en Kinshasa, en el actual República Democrática del Congo."},{"id":"q3","question":"¿Quién se convirtió en 1986 en el campeón pesado más joven de la historia, con solo 20 años?","options":[{"id":"a","text":"Evander Holyfield","is_correct":false},{"id":"b","text":"Lennox Lewis","is_correct":false},{"id":"c","text":"Mike Tyson","is_correct":true},{"id":"d","text":"Riddick Bowe","is_correct":false}],"explanation":"Mike Tyson noqueó a Trevor Berbick y ganó el título pesado del CMB con 20 años y 4 meses."},{"id":"q4","question":"¿Qué peso pesado se retiró invicto con una marca de 49-0?","options":[{"id":"a","text":"Joe Louis","is_correct":false},{"id":"b","text":"Rocky Marciano","is_correct":true},{"id":"c","text":"Jack Dempsey","is_correct":false},{"id":"d","text":"Sonny Liston","is_correct":false}],"explanation":"Rocky Marciano se retiró en 1956 con 49 victorias, 43 por nocaut, sin perder nunca como profesional."},{"id":"q5","question":"¿Cuántos asaltos tiene hoy un combate masculino por el título mundial de boxeo?","options":[{"id":"a","text":"10","is_correct":false},{"id":"b","text":"15","is_correct":false},{"id":"c","text":"8","is_correct":false},{"id":"d","text":"12","is_correct":true}],"explanation":"Las peleas de título masculinas pasaron de 15 a 12 asaltos durante la década de 1980; las femeninas se disputan a diez."},{"id":"q6","question":"¿Qué campeón panameño era conocido como «Manos de Piedra»?","options":[{"id":"a","text":"Alexis Argüello","is_correct":false},{"id":"b","text":"Julio César Chávez","is_correct":false},{"id":"c","text":"Roberto Durán","is_correct":true},{"id":"d","text":"Carlos Monzón","is_correct":false}],"explanation":"Roberto Durán, «Manos de Piedra», fue campeón mundial en cuatro categorías de peso."},{"id":"q7","question":"¿Qué categoría de peso está justo por debajo de la división pesada?","options":[{"id":"a","text":"Semipesado","is_correct":false},{"id":"b","text":"Supermediano","is_correct":false},{"id":"c","text":"Wélter","is_correct":false},{"id":"d","text":"Crucero","is_correct":true}],"explanation":"El peso crucero, con un límite clásico de 200 libras, hace de puente hacia la división pesada."},{"id":"q8","question":"¿Qué campeón pesado era apodado «el Bombardero Café»?","options":[{"id":"a","text":"Joe Louis","is_correct":true},{"id":"b","text":"Muhammad Ali","is_correct":false},{"id":"c","text":"Larry Holmes","is_correct":false},{"id":"d","text":"Floyd Patterson","is_correct":false}],"explanation":"Joe Louis retuvo la corona pesada casi 12 años y la defendió 25 veces, récord de la categoría."}]'::jsonb,
