values (
  'en-mma-ufc-trivia',
  'MMA & UFC Trivia: From UFC 1 to Modern Legends',
  'From the rule-free early tournaments to title-fight records and undefeated champions: how well do you know mixed martial arts?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"In which year was the first UFC event held?","options":[{"id":"a","text":"1990","is_correct":false},{"id":"b","text":"1993","is_correct":true},{"id":"c","text":"1997","is_correct":false},{"id":"d","text":"2001","is_correct":false}],"explanation":"UFC 1 took place in November 1993 in Denver, Colorado, as an eight-man open-weight tournament."},{"id":"q2","question":"Who won the UFC 1 tournament?","options":[{"id":"a","text":"Ken Shamrock","is_correct":false},{"id":"b","text":"Dan Severn","is_correct":false},{"id":"c","text":"Mark Coleman","is_correct":false},{"id":"d","text":"Royce Gracie","is_correct":true}],"explanation":"Royce Gracie submitted three opponents in one night, proving the power of Brazilian jiu-jitsu."},{"id":"q3","question":"Which martial art did Royce Gracie use to dominate the early UFC tournaments?","options":[{"id":"a","text":"Brazilian jiu-jitsu","is_correct":true},{"id":"b","text":"Wrestling","is_correct":false},{"id":"c","text":"Kickboxing","is_correct":false},{"id":"d","text":"Judo","is_correct":false}],"explanation":"The Gracie family developed Brazilian jiu-jitsu, built around leverage and submissions from the ground."},{"id":"q4","question":"What shape is the UFC fighting enclosure?","options":[{"id":"a","text":"Square","is_correct":false},{"id":"b","text":"Circle","is_correct":false},{"id":"c","text":"Octagon","is_correct":true},{"id":"d","text":"Hexagon","is_correct":false}],"explanation":"The eight-sided cage gave the Octagon its name and became the sport''s most recognizable symbol."},{"id":"q5","question":"How many five-minute rounds does a UFC title fight have?","options":[{"id":"a","text":"3","is_correct":false},{"id":"b","text":"4","is_correct":false},{"id":"c","text":"7","is_correct":false},{"id":"d","text":"5","is_correct":true}],"explanation":"Championship fights and main events run five rounds; standard bouts have three."},{"id":"q6","question":"Who became the first UFC women''s champion?","options":[{"id":"a","text":"Miesha Tate","is_correct":false},{"id":"b","text":"Gina Carano","is_correct":false},{"id":"c","text":"Cris Cyborg","is_correct":false},{"id":"d","text":"Ronda Rousey","is_correct":true}],"explanation":"Ronda Rousey was crowned the inaugural women''s bantamweight champion and headlined the first UFC women''s fight at UFC 157 in 2013."},{"id":"q7","question":"Which fighter holds the record for the longest UFC title reign, at nearly seven years?","options":[{"id":"a","text":"Anderson Silva","is_correct":true},{"id":"b","text":"Georges St-Pierre","is_correct":false},{"id":"c","text":"Jon Jones","is_correct":false},{"id":"d","text":"Demetrious Johnson","is_correct":false}],"explanation":"Anderson Silva held the middleweight title from 2006 to 2013, about 2,457 days with 10 straight defenses."},{"id":"q8","question":"Which lightweight champion retired undefeated with a 29-0 record?","options":[{"id":"a","text":"Conor McGregor","is_correct":false},{"id":"b","text":"Khabib Nurmagomedov","is_correct":true},{"id":"c","text":"Tony Ferguson","is_correct":false},{"id":"d","text":"B.J. Penn","is_correct":false}],"explanation":"Khabib Nurmagomedov retired in 2020 after defending the lightweight belt three times without a single loss."}]'::jsonb,
  null,
  array['mma', 'ufc', 'sports', 'trivia']::text[],
  3,
