values (
  'en-martial-arts-trivia',
  'Martial Arts Trivia: Origins, Belts and Masters',
  'Judo, karate, taekwondo, kung fu and beyond: the countries, founders and traditions behind the world''s great martial arts.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"Who founded judo in Japan in 1882?","options":[{"id":"a","text":"Morihei Ueshiba","is_correct":false},{"id":"b","text":"Jigoro Kano","is_correct":true},{"id":"c","text":"Gichin Funakoshi","is_correct":false},{"id":"d","text":"Mas Oyama","is_correct":false}],"explanation":"Jigoro Kano created judo — ''the gentle way'' — by refining the techniques of traditional jujutsu."},{"id":"q2","question":"Karate developed on which island chain before spreading through Japan?","options":[{"id":"a","text":"Hokkaido","is_correct":false},{"id":"b","text":"Kyushu","is_correct":false},{"id":"c","text":"Hawaii","is_correct":false},{"id":"d","text":"Okinawa","is_correct":true}],"explanation":"Karate grew out of the fighting traditions of Okinawa, in the Ryukyu archipelago."},{"id":"q3","question":"Taekwondo is the national martial art of which country?","options":[{"id":"a","text":"South Korea","is_correct":true},{"id":"b","text":"Japan","is_correct":false},{"id":"c","text":"China","is_correct":false},{"id":"d","text":"Thailand","is_correct":false}],"explanation":"Taekwondo, famous for its high kicks, became a full Olympic sport at Sydney 2000."},{"id":"q4","question":"Which striking art is known as ''the art of eight limbs''?","options":[{"id":"a","text":"Karate","is_correct":false},{"id":"b","text":"Muay Thai","is_correct":true},{"id":"c","text":"Kung fu","is_correct":false},{"id":"d","text":"Capoeira","is_correct":false}],"explanation":"Muay Thai, from Thailand, uses fists, elbows, knees and shins — eight points of contact."},{"id":"q5","question":"In which country did capoeira originate?","options":[{"id":"a","text":"Portugal","is_correct":false},{"id":"b","text":"Cuba","is_correct":false},{"id":"c","text":"Brazil","is_correct":true},{"id":"d","text":"Angola","is_correct":false}],"explanation":"Capoeira was developed by enslaved Africans in Brazil, blending fight, dance and music."},{"id":"q6","question":"Who created Jeet Kune Do, ''the way of the intercepting fist''?","options":[{"id":"a","text":"Jackie Chan","is_correct":false},{"id":"b","text":"Jet Li","is_correct":false},{"id":"c","text":"Bruce Lee","is_correct":true},{"id":"d","text":"Chuck Norris","is_correct":false}],"explanation":"Bruce Lee founded Jeet Kune Do in the 1960s as a philosophy of directness and efficiency."},{"id":"q7","question":"Which score ends a judo bout immediately?","options":[{"id":"a","text":"Ippon","is_correct":true},{"id":"b","text":"Waza-ari","is_correct":false},{"id":"c","text":"Yuko","is_correct":false},{"id":"d","text":"Shido","is_correct":false}],"explanation":"An ippon — a clean throw, hold or submission — wins the match on the spot."},{"id":"q8","question":"Which Chinese monastery is linked to the legendary roots of kung fu?","options":[{"id":"a","text":"Wudang","is_correct":false},{"id":"b","text":"Emei","is_correct":false},{"id":"c","text":"Shaolin","is_correct":true},{"id":"d","text":"Todai-ji","is_correct":false}],"explanation":"The Shaolin monastery in Henan province is famed for uniting Chan Buddhism and martial training."}]'::jsonb,
  null,
  array['martial-arts', 'judo', 'karate', 'trivia']::text[],
  3,
