insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-cycling-trivia',
  'Cycling Trivia: Grand Tours and Legendary Champions',
  'Grand Tours, iconic jerseys and the Hell of the North: how much do you know about cycling''s greatest races and champions?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"In which year was the first Tour de France held?","options":[{"id":"a","text":"1896","is_correct":false},{"id":"b","text":"1903","is_correct":true},{"id":"c","text":"1910","is_correct":false},{"id":"d","text":"1921","is_correct":false}],"explanation":"The first Tour de France ran in July 1903, organized by the newspaper L''Auto."},{"id":"q2","question":"What does the yellow jersey signify in the Tour de France?","options":[{"id":"a","text":"Best sprinter","is_correct":false},{"id":"b","text":"Best climber","is_correct":false},{"id":"c","text":"Overall race leader","is_correct":true},{"id":"d","text":"Best young rider","is_correct":false}],"explanation":"The maillot jaune goes to the rider with the lowest cumulative time — the leader of the general classification."},{"id":"q3","question":"What colour is the leader''s jersey in the Giro d''Italia?","options":[{"id":"a","text":"Pink","is_correct":true},{"id":"b","text":"Yellow","is_correct":false},{"id":"c","text":"Red","is_correct":false},{"id":"d","text":"White","is_correct":false}],"explanation":"The maglia rosa is pink, matching the pages of La Gazzetta dello Sport, the race''s founder."},{"id":"q4","question":"In the Tour de France, what is awarded the polka-dot jersey?","options":[{"id":"a","text":"Points classification","is_correct":false},{"id":"b","text":"Mountains classification","is_correct":true},{"id":"c","text":"Team classification","is_correct":false},{"id":"d","text":"Combativity prize","is_correct":false}],"explanation":"The polka-dot jersey goes to the best climber — the King (or Queen) of the Mountains."},{"id":"q5","question":"What is the record for most Tour de France overall victories?","options":[{"id":"a","text":"4","is_correct":false},{"id":"b","text":"6","is_correct":false},{"id":"c","text":"7","is_correct":false},{"id":"d","text":"5","is_correct":true}],"explanation":"Five wins, shared by Jacques Anquetil, Eddy Merckx, Bernard Hinault and Miguel Indurain."},{"id":"q6","question":"What nickname did Eddy Merckx earn for devouring every race in sight?","options":[{"id":"a","text":"The Badger","is_correct":false},{"id":"b","text":"The Cannibal","is_correct":true},{"id":"c","text":"The Eagle","is_correct":false},{"id":"d","text":"The Pirate","is_correct":false}],"explanation":"The Belgian won everything — ''The Cannibal'' took five Tours, five Giros and countless classics."},{"id":"q7","question":"Which of these races is one of the three Grand Tours?","options":[{"id":"a","text":"Paris–Roubaix","is_correct":false},{"id":"b","text":"Tour of Flanders","is_correct":false},{"id":"c","text":"Vuelta a España","is_correct":true},{"id":"d","text":"Critérium du Dauphiné","is_correct":false}],"explanation":"The three-week Grand Tours are the Tour de France, the Giro d''Italia and the Vuelta a España."},{"id":"q8","question":"Which cobbled classic is known as ''The Hell of the North''?","options":[{"id":"a","text":"Milan–San Remo","is_correct":false},{"id":"b","text":"Liège–Bastogne–Liège","is_correct":false},{"id":"c","text":"Paris–Roubaix","is_correct":true},{"id":"d","text":"Strade Bianche","is_correct":false}],"explanation":"Paris–Roubaix crosses brutal cobblestone sectors in northern France — ''l''enfer du Nord''."}]'::jsonb,
  null,
  array['cycling', 'tour-de-france', 'sports', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
