  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"¿En qué año se corrió el primer Tour de Francia?","options":[{"id":"a","text":"1896","is_correct":false},{"id":"b","text":"1910","is_correct":false},{"id":"c","text":"1903","is_correct":true},{"id":"d","text":"1921","is_correct":false}],"explanation":"El primer Tour de Francia se disputó en julio de 1903, organizado por el diario L''Auto."},{"id":"q2","question":"¿Qué significa el maillot amarillo en el Tour de Francia?","options":[{"id":"a","text":"Mejor velocista","is_correct":false},{"id":"b","text":"Líder de la clasificación general","is_correct":true},{"id":"c","text":"Mejor escalador","is_correct":false},{"id":"d","text":"Mejor corredor joven","is_correct":false}],"explanation":"El maillot amarillo lo lleva quien tiene el menor tiempo acumulado: el líder de la general."},{"id":"q3","question":"¿De qué color es el jersey del líder del Giro de Italia?","options":[{"id":"a","text":"Amarillo","is_correct":false},{"id":"b","text":"Rojo","is_correct":false},{"id":"c","text":"Blanco","is_correct":false},{"id":"d","text":"Rosa","is_correct":true}],"explanation":"La maglia rosa es rosa, como el papel de La Gazzetta dello Sport, el diario fundador de la carrera."},{"id":"q4","question":"¿Qué premia el maillot de lunares rojos del Tour de Francia?","options":[{"id":"a","text":"Clasificación por puntos","is_correct":false},{"id":"b","text":"Clasificación de la montaña","is_correct":true},{"id":"c","text":"Clasificación por equipos","is_correct":false},{"id":"d","text":"Premio de la combatividad","is_correct":false}],"explanation":"El maillot de lunares distingue al mejor escalador, el «rey de la montaña»."},{"id":"q5","question":"¿Cuál es el récord de victorias absolutas en el Tour de Francia?","options":[{"id":"a","text":"4","is_correct":false},{"id":"b","text":"6","is_correct":false},{"id":"c","text":"5","is_correct":true},{"id":"d","text":"7","is_correct":false}],"explanation":"Cinco triunfos, compartidos por Jacques Anquetil, Eddy Merckx, Bernard Hinault y Miguel Indurain."},{"id":"q6","question":"¿Qué apodo ganó Eddy Merckx por devorar cada carrera que disputaba?","options":[{"id":"a","text":"El Tejón","is_correct":false},{"id":"b","text":"El Águila","is_correct":false},{"id":"c","text":"El Pirata","is_correct":false},{"id":"d","text":"El Caníbal","is_correct":true}],"explanation":"El belga lo ganó todo: «El Caníbal» sumó cinco Tours, cinco Giros e incontables clásicas."},{"id":"q7","question":"¿Cuál de estas carreras es una de las tres Grandes Vueltas?","options":[{"id":"a","text":"París-Roubaix","is_correct":false},{"id":"b","text":"La Vuelta a España","is_correct":true},{"id":"c","text":"Tour de Flandes","is_correct":false},{"id":"d","text":"Critérium du Dauphiné","is_correct":false}],"explanation":"Las Grandes Vueltas de tres semanas son el Tour de Francia, el Giro de Italia y la Vuelta a España."},{"id":"q8","question":"¿Qué clásica de adoquines es conocida como «El Infierno del Norte»?","options":[{"id":"a","text":"Milán-San Remo","is_correct":false},{"id":"b","text":"Lieja-Bastoña-Lieja","is_correct":false},{"id":"c","text":"Strade Bianche","is_correct":false},{"id":"d","text":"París-Roubaix","is_correct":true}],"explanation":"La París-Roubaix cruza brutales sectores de adoquín en el norte de Francia: «l''enfer du Nord»."}]'::jsonb,
